def send_telegram(chat_id, message):
    if not TELEGRAM_BOT_TOKEN or not chat_id:
        logger.warning("Telegram no configurado correctamente")
        return False
    try:
        r = requests.post(f"{TELEGRAM_API_URL}/sendMessage", json={"chat_id":chat_id,"text":message,"parse_mode":"HTML"}, timeout=10)
        if r.status_code == 200:
            logger.info(f"Telegram enviado a {chat_id}")
            return True
        else:
            logger.error(f"Error Telegram: {r.status_code} - {r.text}")
            return False
    except Exception as e:
        logger.error(f"Error Telegram: {e}")
        return False

