def generate_beep_base64(freq=880, duration=0.28, sample_rate=44100):
    t = np.linspace(0, duration, int(sample_rate*duration), False)
    tone = 0.45 * np.sin(freq * 2 * np.pi * t)
    audio = np.int16(tone * 32767)
    buf = io.BytesIO()
    with wave.open(buf, 'wb') as wf:
        wf.setnchannels(1); wf.setsampwidth(2); wf.setframerate(sample_rate)
        wf.writeframes(struct.pack('<' + ('h'*len(audio)), *audio))
    return base64.b64encode(buf.getvalue()).decode()

def play_critical_alarm(event_id):
    if st.session_state.get("last_beep_event") == event_id: return
    st.session_state.last_beep_event = event_id
    if HAS_WINSOUND:
        for _ in range(3): winsound.Beep(1000, 300); time.sleep(0.1)
        st.error("ALARMA CRITICA: Se requiere atencion inmediata")
    else:
        b64 = generate_beep_base64()
        st.markdown(f'<audio autoplay><source src="data:audio/wav;base64,{b64}" type="audio/wav"></audio>', unsafe_allow_html=True)
        st.error("ALARMA CRITICA")

def play_observation_alarm(event_id):
    if st.session_state.get("last_observation_event") == event_id: return
    st.session_state.last_observation_event = event_id
    if HAS_WINSOUND:
        for _ in range(2): winsound.Beep(600, 200); time.sleep(0.1)
        st.warning("Observacion: revisar condicion")
    else:
        b64 = generate_beep_base64(freq=600, duration=0.2)
        st.markdown(f'<audio autoplay><source src="data:audio/wav;base64,{b64}" type="audio/wav"></audio>', unsafe_allow_html=True)
        st.warning("Observacion")

