def init_user_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("""CREATE TABLE IF NOT EXISTS users (dni TEXT PRIMARY KEY, full_name TEXT NOT NULL, occupation TEXT, area TEXT, password_hash TEXT NOT NULL, salt TEXT NOT NULL, created_at TEXT NOT NULL, last_login TEXT)""")
    c.execute("""CREATE TABLE IF NOT EXISTS work_orders (ot_id TEXT PRIMARY KEY, asset_name TEXT NOT NULL, alert_id TEXT, description TEXT, priority TEXT NOT NULL, responsible TEXT, creation_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pendiente', maintenance_decision TEXT, observations TEXT, closed_date TEXT, created_by TEXT, updated_at TEXT)""")
    c.execute("""CREATE TABLE IF NOT EXISTS circular_interventions (id INTEGER PRIMARY KEY AUTOINCREMENT, ot_id TEXT NOT NULL, component TEXT NOT NULL, decision TEXT NOT NULL, result TEXT, mass_conserved_kg REAL DEFAULT 0, mass_discarded_kg REAL DEFAULT 0, evidence TEXT, recorded_date TEXT NOT NULL, recorded_by TEXT, FOREIGN KEY (ot_id) REFERENCES work_orders(ot_id))""")
    c.execute("""CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT NOT NULL, user_dni TEXT, action TEXT NOT NULL, details TEXT, ip_address TEXT)""")
    conn.commit(); conn.close()

def hash_password(password, salt=None):
    if salt is None: salt = os.urandom(16).hex()
    hashed = hashlib.sha256((password + salt).encode("utf-8")).hexdigest()
    return hashed, salt

def create_user(dni, full_name, occupation, area, password):
    conn = sqlite3.connect(DB_PATH); c = conn.cursor()
    try:
        hashed, salt = hash_password(password)
        c.execute("INSERT INTO users VALUES (?,?,?,?,?,?,?,?)", (dni,full_name,occupation,area,hashed,salt,datetime.now().isoformat(),""))
        conn.commit(); log_audit(dni, "CREATE_USER", f"Usuario creado: {full_name}")
        return True, "Usuario creado correctamente."
    except sqlite3.IntegrityError:
        return False, "Ese DNI ya esta registrado."
    finally: conn.close()

def validate_login(dni, password):
    conn = sqlite3.connect(DB_PATH); c = conn.cursor()
    c.execute("SELECT dni,full_name,occupation,area,password_hash,salt FROM users WHERE dni=?", (dni,))
    row = c.fetchone(); conn.close()
    if row:
        stored_hash = row[4]; salt = row[5]
        hashed, _ = hash_password(password, salt)
        if hashed == stored_hash:
            conn = sqlite3.connect(DB_PATH)
            conn.execute("UPDATE users SET last_login=? WHERE dni=?", (datetime.now().isoformat(), dni))
            conn.commit(); conn.close()
            log_audit(dni, "LOGIN", "Inicio de sesion exitoso")
            return {"dni":row[0],"full_name":row[1],"occupation":row[2],"area":row[3]}
    return None

def log_audit(user_dni, action, details):
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute("INSERT INTO audit_logs (timestamp, user_dni, action, details) VALUES (?, ?, ?, ?)", (datetime.now().isoformat(), user_dni, action, details))
        conn.commit(); conn.close()
    except Exception as e:
        logger.error(f"Error al registrar auditoria: {e}")

