def create_work_order_db(ot_data):
    conn = sqlite3.connect(DB_PATH); c = conn.cursor()
    try:
        c.execute("""INSERT INTO work_orders (ot_id, asset_name, alert_id, description, priority, responsible, creation_date, status, created_by, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (ot_data["ot_id"], ot_data["asset_name"], ot_data.get("alert_id"), ot_data["description"], ot_data["priority"], ot_data.get("responsible"), ot_data["creation_date"], ot_data["status"], ot_data.get("created_by"), datetime.now().isoformat()))
        conn.commit()
        log_audit(ot_data.get("created_by"), "CREATE_OT", f"OT creada: {ot_data['ot_id']}")
        notify_ot_creation(ot_data)
        return True
    except Exception as e:
        logger.error(f"Error al crear OT: {e}")
        return False
    finally: conn.close()

def update_work_order_status(ot_id, new_status, user_dni, observations=""):
    valid_transitions = {"Pendiente": ["En Ejecucion", "Cerrada"], "En Ejecucion": ["Cerrada", "Pendiente"], "Cerrada": ["Pendiente"]}
    conn = sqlite3.connect(DB_PATH); c = conn.cursor()
    c.execute("SELECT status FROM work_orders WHERE ot_id=?", (ot_id,))
    row = c.fetchone()
    if not row: conn.close(); return False
    current_status = row[0]
    if new_status not in valid_transitions.get(current_status, []): conn.close(); return False
    c.execute("UPDATE work_orders SET status=?, observations=?, updated_at=? WHERE ot_id=?", (new_status, observations, datetime.now().isoformat(), ot_id))
    conn.commit()
    if new_status == "Cerrada":
        c.execute("SELECT * FROM work_orders WHERE ot_id=?", (ot_id,))
        ot_row = dict(c.fetchone())
        notify_ot_completion(ot_row)
    conn.close()
    log_audit(user_dni, "UPDATE_OT", f"OT {ot_id}: {current_status} -> {new_status}")
    return True

def get_all_work_orders():
    conn = sqlite3.connect(DB_PATH); conn.row_factory = sqlite3.Row; c = conn.cursor()
    c.execute("SELECT * FROM work_orders ORDER BY creation_date DESC")
    orders = [dict(row) for row in c.fetchall()]; conn.close()
    return orders

def get_work_order(ot_id):
    conn = sqlite3.connect(DB_PATH); conn.row_factory = sqlite3.Row; c = conn.cursor()
    c.execute("SELECT * FROM work_orders WHERE ot_id=?", (ot_id,))
    row = c.fetchone(); conn.close()
    return dict(row) if row else None

def record_circular_intervention(intervention_data):
    conn = sqlite3.connect(DB_PATH); c = conn.cursor()
    try:
        c.execute("""INSERT INTO circular_interventions (ot_id, component, decision, result, mass_conserved_kg, mass_discarded_kg, evidence, recorded_date, recorded_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (intervention_data["ot_id"], intervention_data["component"], intervention_data["decision"], intervention_data.get("result"), intervention_data.get("mass_conserved_kg", 0), intervention_data.get("mass_discarded_kg", 0), intervention_data.get("evidence"), datetime.now().isoformat(), intervention_data.get("recorded_by")))
        conn.commit()
        log_audit(intervention_data.get("recorded_by"), "CIRCULAR_INTERVENTION", f"Intervencion registrada para OT {intervention_data['ot_id']}")
        notify_economic_impact(intervention_data)
        return True
    except Exception as e:
        logger.error(f"Error al registrar intervencion circular: {e}")
        return False
    finally: conn.close()

def get_circular_interventions():
    conn = sqlite3.connect(DB_PATH); conn.row_factory = sqlite3.Row; c = conn.cursor()
    c.execute("SELECT * FROM circular_interventions ORDER BY recorded_date DESC")
    interventions = [dict(row) for row in c.fetchall()]; conn.close()
    return interventions

def get_circular_metrics():
    interventions = get_circular_interventions()
    total_interventions = len(interventions)
    repaired_reused = sum(1 for i in interventions if i["decision"] in ["Reparado", "Reutilizado"])
    total_discarded_kg = sum(i["mass_discarded_kg"] or 0 for i in interventions)
    total_conserved_kg = sum(i["mass_conserved_kg"] or 0 for i in interventions)
    return {"total_interventions": total_interventions, "repaired_reused_count": repaired_reused, "total_discarded_kg": total_discarded_kg, "total_conserved_kg": total_conserved_kg}

