def generate_synthetic_data(scenario, n=240, seed=42):
    rng = np.random.default_rng(seed); t = np.arange(n)
    start = datetime.now() - timedelta(hours=n)
    dates = [start + timedelta(hours=int(i)) for i in t]
    vibration = 2.8 + 0.28*rng.normal(size=n) + 0.12*np.sin(t/9)
    temperature = 66 + 1.6*rng.normal(size=n) + 0.5*np.sin(t/12)
    vacuum = -72 + 1.2*rng.normal(size=n) + 0.7*np.sin(t/10)
    if scenario == "Degradacion progresiva": vibration += np.linspace(0,4.1,n); temperature += np.linspace(0,16,n); vacuum += np.linspace(0,18,n)
    elif scenario == "Condicion critica": vibration += np.linspace(1.5,6,n)+0.45*np.sin(t/3.5); temperature += np.linspace(8,24,n)+0.9*np.sin(t/5); vacuum += np.linspace(10,28,n)
    elif scenario == "Fuga subito": step = int(n*0.55); vibration += np.linspace(0,1.2,n); temperature += np.linspace(0,5.5,n); vacuum[step:] += 18.5; vacuum[step+12:] += 6
    elif scenario == "Rodamiento degradado": vibration += np.linspace(0.4,5.2,n)+0.8*np.maximum(0,np.sin(t/4)); temperature += np.linspace(1,13,n); vacuum += np.linspace(0,7,n)
    df = pd.DataFrame({"fecha_hora":dates,"vibracion_rms_mm_s":np.round(vibration,3),"temperatura_c":np.round(temperature,2),"presion_vacio_kpa":np.round(vacuum,2)})
    return enrich_data(df)

def normalize_uploaded_data(df):
    df = df.copy(); df.columns = [str(c).strip().lower() for c in df.columns]
    rm = {"timestamp":"fecha_hora","fecha":"fecha_hora","datetime":"fecha_hora","time":"fecha_hora","vibracion":"vibracion_rms_mm_s","vibration":"vibracion_rms_mm_s","temperatura":"temperatura_c","temperature":"temperatura_c","temp":"temperatura_c","presion":"presion_vacio_kpa","pressure":"presion_vacio_kpa","vacio":"presion_vacio_kpa","vacuum":"presion_vacio_kpa"}
    df = df.rename(columns={k:v for k,v in rm.items() if k in df.columns})
    req = ["vibracion_rms_mm_s","temperatura_c","presion_vacio_kpa"]
    miss = [c for c in req if c not in df.columns]
    if miss: raise ValueError(f"Faltan columnas: {miss}")
    if "fecha_hora" not in df.columns: df["fecha_hora"] = [datetime.now()-timedelta(hours=len(df)-i) for i in range(len(df))]
    else:
        df["fecha_hora"] = pd.to_datetime(df["fecha_hora"], errors="coerce")
        if df["fecha_hora"].isna().any(): df["fecha_hora"] = [datetime.now()-timedelta(hours=len(df)-i) for i in range(len(df))]
    df = df[req+["fecha_hora"]].copy()
    for c in req: df[c] = pd.to_numeric(df[c], errors="coerce")
    return enrich_data(df.dropna().sort_values("fecha_hora").reset_index(drop=True))

def risk_vibration(v): return float(np.clip((v-3)/(8.5-3)*100,0,100))
def risk_temperature(t): return float(np.clip((t-68)/(92-68)*100,0,100))
def risk_vacuum(p): return float(np.clip((p-(-72))/((-45)-(-72))*100,0,100))

def variable_status(row):
    v,t,p = row["vibracion_rms_mm_s"],row["temperatura_c"],row["presion_vacio_kpa"]
    return {"Vibracion":"Critico" if v>=THRESHOLDS["vibration_alert"] else "Alerta" if v>=THRESHOLDS["vibration_normal"] else "Normal",
            "Temperatura":"Critico" if t>=THRESHOLDS["temperature_alert"] else "Alerta" if t>=THRESHOLDS["temperature_normal"] else "Normal",
            "Presion de vacio":"Critico" if p>=THRESHOLDS["vacuum_alert"] else "Alerta" if p>=THRESHOLDS["vacuum_normal"] else "Normal"}

def classify_risk(ir, row=None):
    if row is not None:
        s = variable_status(row).values()
        if "Critico" in s: return "Critico"
        if "Alerta" in s and ir >= 35: return "Alerta"
    if ir<40: return "Normal"
    if ir<70: return "Alerta"
    return "Critico"

def enrich_data(df):
    df = df.copy()
    df["riesgo_vibracion"] = df["vibracion_rms_mm_s"].apply(risk_vibration)
    df["riesgo_temperatura"] = df["temperatura_c"].apply(risk_temperature)
    df["riesgo_vacio"] = df["presion_vacio_kpa"].apply(risk_vacuum)
    df["indice_riesgo"] = (0.45*df["riesgo_vibracion"]+0.30*df["riesgo_temperatura"]+0.25*df["riesgo_vacio"]).round(1)
    df["estado"] = [classify_risk(ir, df.iloc[i]) for i,ir in enumerate(df["indice_riesgo"])]
    return df

def get_alarms(row):
    alarms = []; s = variable_status(row)
    if s["Vibracion"]!="Normal": alarms.append((s["Vibracion"],"Vibracion",f"{row['vibracion_rms_mm_s']:.2f} mm/s"))
    if s["Temperatura"]!="Normal": alarms.append((s["Temperatura"],"Temperatura",f"{row['temperatura_c']:.1f} C"))
    if s["Presion de vacio"]!="Normal": alarms.append((s["Presion de vacio"],"Presion de vacio",f"{row['presion_vacio_kpa']:.1f} kPa"))
    return alarms

def create_work_order_obj(row, asset_name, source="Automatica"):
    alarms = get_alarms(row)
    priority = "P0" if row["estado"]=="Critico" else "P1" if row["estado"]=="Alerta" else "P2"
    symptoms = "; ".join([f"{name}: {value} ({level})" for level,name,value in alarms]) or "Sin alarma critica"
    tasks = []
    if any(a[1]=="Vibracion" for a in alarms): tasks += ["Medir vibracion en rodamientos","Verificar alineacion","Inspeccionar holguras"]
    if any(a[1]=="Temperatura" for a in alarms): tasks += ["Revisar lubricacion","Verificar friccion interna","Inspeccionar ventilacion"]
    if any(a[1]=="Presion de vacio" for a in alarms): tasks += ["Prueba de fugas","Inspeccionar sellos","Revisar tuberias y filtros"]
    if not tasks: tasks = ["Inspeccion rutinaria","Registrar lectura y tendencia"]
    ts = pd.to_datetime(row["fecha_hora"]).strftime("%Y%m%d%H%M")
    return {"ot_id":f"OT-{ts}-{priority}","asset_name":asset_name,"alert_id":f"ALM-{ts}","description":f"Anomalia detectada: {symptoms}","priority":priority,"responsible":"","creation_date":datetime.now().strftime("%Y-%m-%d %H:%M:%S"),"status":"Pendiente","maintenance_decision":"","observations":"","created_by":st.session_state.get("auth_user",{}).get("dni","sistema")}

def calculate_kpis(oh,failures,dh,pmd,pmp,ph,ahw,pr):
    mtbf = oh/failures if failures else float("inf")
    mttr = dh/failures if failures else 0
    avail = mtbf/(mtbf+mttr) if math.isfinite(mtbf) and (mtbf+mttr) else 1
    rel24 = math.exp(-24/mtbf) if math.isfinite(mtbf) and mtbf>0 else 1
    pmc = pmd/pmp if pmp else 0
    bl = ph/ahw if ahw else 0
    pl = dh*pr
    return {"MTBF (h)":mtbf,"MTTR (h)":mttr,"Disponibilidad (%)":avail*100,"Confiabilidad 24h (%)":rel24*100,"Cumplimiento PM (%)":pmc*100,"Backlog (semanas)":bl,"Perdida productiva (t)":pl}

