def sanitize_text(text):
    text = text.replace("\x00"," "); text = re.sub(r"\s+"," ",text); return text.strip()

def split_text_to_chunks(text, source_name, chunk_size=900, overlap=150):
    text = sanitize_text(text)
    if not text: return []
    chunks=[]; start=0; idx=0
    while start<len(text):
        end=min(len(text),start+chunk_size); chunks.append({"source":source_name,"text":text[start:end],"idx":idx}); idx+=1; start=end-overlap
    return chunks

def _extract_pages_from_pdf_bytes(file_bytes, file_name, max_page_chars=1800):
    pages=[]
    if HAS_FITZ:
        doc=fitz.open(stream=file_bytes,filetype="pdf")
        for i in range(len(doc)):
            try: txt=sanitize_text(doc[i].get_text("text") or "")
            except: txt=""
            if txt: pages.append({"source":file_name,"page":i+1,"text":txt[:max_page_chars]})
        doc.close()
    elif HAS_PDF:
        reader=PdfReader(io.BytesIO(file_bytes))
        for i,page in enumerate(reader.pages):
            try: txt=sanitize_text(page.extract_text() or " ")
            except: txt=" "
            if txt: pages.append({"source":file_name,"page":i+1,"text":txt[:max_page_chars]})
    return pages

def load_knowledge_files(uploaded_files, workers=4):
    if not uploaded_files: return [],[],[]
    file_packs=[(f.name,f.getvalue()) for f in uploaded_files]
    workers=max(1,min(int(workers),len(file_packs)))
    docs=[]; page_index=[]; skipped=[]
    def process_file(fp):
        fn,fb=fp; ext=os.path.splitext(fn.lower())[1]; pil=[]; ds={"name":fn,"pages":0,"chars_indexed":0,"status":"OK"}
        try:
            if ext==".pdf":
                pil=_extract_pages_from_pdf_bytes(fb,fn)
                if not pil: ds["status"]="Sin texto extraible"
            elif ext in [".txt",".md",".csv"]:
                txt=sanitize_text(fb.decode("utf-8",errors="ignore")); ch=split_text_to_chunks(txt,fn,1500,150)
                pil=[{"source":c["source"],"page":c["idx"]+1,"text":c["text"]} for c in ch]
            elif ext==".docx" and HAS_DOCX:
                docx=Document(io.BytesIO(fb)); txt=sanitize_text("\n".join([p.text for p in docx.paragraphs]))
                ch=split_text_to_chunks(txt,fn,1500,150); pil=[{"source":c["source"],"page":c["idx"]+1,"text":c["text"]} for c in ch]
            else: ds["status"]="Formato no soportado"
            ds["pages"]=len(pil); ds["chars_indexed"]=sum(len(p["text"]) for p in pil)
            return ds,pil,None
        except Exception as e:
            ds["status"]=f"Error: {e}"; return ds,[],fn
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futs=[ex.submit(process_file,p) for p in file_packs]
        for fut in as_completed(futs):
            ds,pi,sf=fut.result(); docs.append(ds); page_index.extend(pi)
            if sf: skipped.append(sf)
    return docs,[{"source":p["source"],"idx":p["page"],"text":p["text"]} for p in page_index],skipped

def retrieve_kb_context(query, top_k=5):
    chunks=st.session_state.get("kb_chunks",[])
    if not chunks: return "No hay base de conocimiento cargada."
    qw=set(re.findall(r"[a-zA-Z0-9]+",query.lower())); scored=[]
    for ch in chunks:
        tl=ch["text"].lower(); ws=set(re.findall(r"[a-zA-Z0-9]+",tl))
        ov=len(qw.intersection(ws)); bn=sum(2 for term in ["vibracion","temperatura","vacio","bomba","rodamiento","mantenimiento","falla","lubricacion"] if term in tl and term in query.lower())
        if ov+bn>0: scored.append((ov+bn,ch))
    picked=chunks[:top_k] if not scored else [x[1] for x in sorted(scored,key=lambda x:x[0],reverse=True)[:top_k]]
    return "\n\n".join([f"Fuente: {p.get('source','documento')} | Pagina: {p.get('idx',p.get('page',''))} | Extracto: {p['text'][:900]}" for p in picked])

