def call_ollama_assistant(user_text, row, kpi_values, asset_name, base_url, model):
    if not HAS_REQUESTS: return "No se encontro requests."
    base_url=(base_url or "http://localhost:11434").rstrip("/")
    sys_prompt="Eres Tech Maint Pro, asistente experto en mantenimiento industrial y economia circular. Responde en espanol, claro y accionable. Usa contexto tecnico, documentos, AMEF/RCM y lecturas actuales. No inventes datos."
    alarms=get_alarms(row); at="; ".join([f"{n}: {v} ({l})" for l,n,v in alarms]) or "Sin alarmas activas"
    fm="\n".join([f"- Sintoma: {i['symptom']} | Modo: {i['failure_mode']} | Efecto: {i['effect']} | Criticidad: {i['criticality']}" for i in FMECA_KNOWLEDGE])
    kt="\n".join([f"- {k}: {v:.2f}" for k,v in kpi_values.items()]); kb=retrieve_kb_context(user_text)
    ctx=f"CONTEXTO:\nActivo: {asset_name} ({ASSETS[asset_name]['tag']}). Criticidad: {ASSETS[asset_name]['criticality']}.\nLECTURAS: Estado: {row['estado']}, IR: {row['indice_riesgo']:.1f}/100, Vibracion: {row['vibracion_rms_mm_s']:.2f} mm/s, Temp: {row['temperatura_c']:.1f} C, Vacio: {row['presion_vacio_kpa']:.1f} kPa. Alarmas: {at}.\nUMBRALES: Vibracion normal<{THRESHOLDS['vibration_normal']}, alerta>={THRESHOLDS['vibration_normal']}, critico>={THRESHOLDS['vibration_alert']}. Temp normal<{THRESHOLDS['temperature_normal']}, alerta>={THRESHOLDS['temperature_normal']}, critico>={THRESHOLDS['temperature_alert']}. Vacio normal<{THRESHOLDS['vacuum_normal']}, alerta>={THRESHOLDS['vacuum_normal']}, critico>={THRESHOLDS['vacuum_alert']}.\nAMEF/RCM:\n{fm}\nBASE CONOCIMIENTO:\n{kb}\nKPIs:\n{kt}"
    try:
        r=requests.post(f"{base_url}/api/chat",json={"model":model,"messages":[{"role":"system","content":sys_prompt},{"role":"user","content":f"{ctx}\n\nCONSULTA:\n{user_text}"}],"stream":False,"options":{"temperature":0.2,"num_predict":900}},timeout=140)
        if r.status_code==404: return f"No se encontro modelo '{model}'."
        r.raise_for_status(); return r.json().get("message",{}).get("content","Sin contenido.")
    except Exception as e: return f"Error Ollama: {e}"

def chatbot_response(user_text, latest, kpi_values, asset_name, use_generative_ai=False, ollama_url="http://localhost:11434", model="llama3.2:1b"):
    if use_generative_ai: return call_ollama_assistant(user_text,latest,kpi_values,asset_name,ollama_url,model)
