        na=[a[1] for a in alarms]
        if "Vibracion" in na and "Temperatura" in na: hip="Posible desgaste de rodamientos, desalineacion o lubricacion deficiente."
        elif "Presion de vacio" in na and "Vibracion" in na: hip="Posible fuga/sello deteriorado con sobreesfuerzo mecanico."
        elif "Presion de vacio" in na: hip="Posible fuga en linea, deterioro de sellos o restriccion en succion."
        elif "Vibracion" in na: hip="Posible desalineacion, desbalance o desgaste de rodamiento."
