def create_single_sensor_chart(df,column,title,y_title,color,threshold_normal=None,threshold_alert=None,reverse=False):
    fig=go.Figure()
    fig.add_trace(go.Scatter(x=df["fecha_hora"],y=df[column],mode="lines+markers",name=title,line=dict(color=color,width=3),marker=dict(size=4),fill="tozeroy" if not reverse else None,fillcolor="rgba(59,130,246,0.08)" if not reverse else None))
    if threshold_normal is not None: fig.add_hline(y=threshold_normal,line_dash="dash",line_color="#f59e0b",annotation_text="Alerta",annotation_position="top right")
    if threshold_alert is not None: fig.add_hline(y=threshold_alert,line_dash="dash",line_color="#991b1b",annotation_text="Critico",annotation_position="top right")
    fig.update_layout(title=dict(text=title,y=0.96,x=0.01,xanchor="left"),template="plotly_dark",paper_bgcolor="rgba(0,0,0,0)",plot_bgcolor="rgba(0,0,0,0)",margin=dict(l=20,r=20,t=78,b=30),xaxis=dict(title="Fecha/hora",showgrid=False),yaxis=dict(title=y_title,autorange="reversed" if reverse else True),hovermode="x unified",showlegend=False,height=360)
    return fig

def create_vibration_chart(df): return create_single_sensor_chart(df,"vibracion_rms_mm_s","Vibracion RMS","Vibracion (mm/s)","#42a5ff",THRESHOLDS["vibration_normal"],THRESHOLDS["vibration_alert"])
def create_temperature_chart(df): return create_single_sensor_chart(df,"temperatura_c","Temperatura","Temperatura (C)","#fbbf24",THRESHOLDS["temperature_normal"],THRESHOLDS["temperature_alert"])
